INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(5601, 'Joshua 9:22', 'Joshua', 9, 22, '&nbsp;يشوَع حُکم وکړو چې د جبعون خلق دې هغۀ له راوستلے شى. او هغۀ د هغوئ نه تپوس وکړو، ”تاسو ولې مونږ دوکه کړُو او راته مو ووئيل چې مونږ د لرې ځائ نه راغلى يُو، اګر چې تاسو دلته نزدې اوسېدئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5602, 'Joshua 9:23', 'Joshua', 9, 23, '&nbsp;د دې کار کولو په وجه تاسو لعنتى شوى يئ. ستاسو خلق به د همېشه دپاره غلامان وى. لرګى به ماتوى او زما د خُدائ پاک کور ته به اوبۀ راوړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5603, 'Joshua 9:24', 'Joshua', 9, 24, '&nbsp;هغوئ په جواب کښې ووئيل، ”صاحِبه، مونږ ځکه داسې وکړل چې مونږ ته پوره خبر رارسېدلے دے چې مالِک خُدائ ستاسو خُدائ پاک خپل خِدمت کوونکى موسىٰ له دا حُکم ورکړے وو چې دا ټول مُلک تاسو له درکړى او چې څومره خلق په هغه مُلک کښې وى نو وبه يې وژنئ. مونږ ستاسو نه سخت يرېدو نو په دې وجه مو دا کار کړے دے او زمونږ سره د خپل ژوند فکر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5604, 'Joshua 9:25', 'Joshua', 9, 25, '&nbsp;اوس مونږ ستاسو په قبضه کښې يُو، څۀ چې درته ښۀ ښکارى نو هم هغه شان وکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5605, 'Joshua 9:26', 'Joshua', 9, 26, '&nbsp;نو يشوَع بنى اِسرائيلو له اجازت ورنۀ کړو چې هغوئ ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5606, 'Joshua 9:27', 'Joshua', 9, 27, '&nbsp;خو هم په هغه وخت هغۀ د هغوئ نه غلامان جوړ کړل چې لرګى ماتوى او د مالِک خُدائ د قربان‌ګاه او بنى اِسرائيلو دپاره اوبۀ راوړى. او تر نن ورځې پورې هغوئ په هغه ځائ کښې هم دا کار کوى چې مالِک خُدائ د خپل عبادت دپاره غوره کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5607, 'Joshua 10:1', 'Joshua', 10, 1, '&nbsp;د يروشلم بادشاه ادونى‌صدق خبر شو چې يشوَع عى قبضه کړے دے او بېخى يې تباه کړے دے او د دې بادشاه يې وژلے دے، لکه څنګه چې يشوَع د يريحو او د دې بادشاه سره هم دغه شان کړى وُو. هغه د دې نه هم خبر شو چې د جبعون خلقو د بنى اِسرائيلو سره صُلح کړې ده او د هغوئ سره اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5608, 'Joshua 10:2', 'Joshua', 10, 2, '&nbsp;د يروشلم خلق د دې په وجه يرې واخستل ځکه چې جبعون د شاهى ښارونو په شان يو لوئ ښار وو، دا د عى نه هم لوئ وو او د دې سړى تکړه جنګيالى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5609, 'Joshua 10:3', 'Joshua', 10, 3, '&nbsp;نو ادونى‌صدق د حبرون بادشاه هوهام له، د يرموت بادشاه پيرام، د لکيس بادشاه يفيع او د عجلون بادشاه دبير له دا پېغام ولېږلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5610, 'Joshua 10:4', 'Joshua', 10, 4, '&nbsp;”راشئ او په جبعون باندې په حمله کولو کښې زما مدد وکړئ، ځکه چې د جبعون خلقو د يشوَع او د بنى اِسرائيلو سره صُلح کړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5611, 'Joshua 10:5', 'Joshua', 10, 5, '&nbsp;دې پينځو امورى بادشاهانو، د يروشلم بادشاه، د حبرون، د يرموت، د لکيس او د عجلون بادشاه يو لښکر جوړ کړو، جبعون يې محاصره کړو او حمله يې ورباندې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5612, 'Joshua 10:6', 'Joshua', 10, 6, '&nbsp;د جبعون سړو يشوَع له دا خبر ورولېږلو چې هغه د جِلجال په کېمپ کښې وو، ”په دې وخت کښې مونږ عاجزان هم داسې مۀ پرېږده. سمدستى راشه او زمونږ مدد وکړه. د غرونو په مُلک کښې ټول امورى بادشاهان په خپلو کښې ملګرى شوى دى او په مونږ يې حمله کړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5613, 'Joshua 10:7', 'Joshua', 10, 7, '&nbsp;نو يشوَع او د هغۀ ټول لښکر د جِلجال نه روان شول چې په دې کښې تکړه فوجيان هم شامل وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5614, 'Joshua 10:8', 'Joshua', 10, 8, '&nbsp;مالِک خُدائ يشوَع ته وفرمائيل، ”د هغوئ نه مۀ يرېږه. ما د مخکښې نه تا له فتح درکړې ده. د هغوئ يو کس به هم ستا مقابله نۀ شى کولے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5615, 'Joshua 10:9', 'Joshua', 10, 9, '&nbsp;يشوَع او د هغۀ لښکر ټوله شپه د جِلجال نه جبعون ته مزل وکړو او هغوئ په اموريانو باندې يوه ناڅاپه حمله وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5616, 'Joshua 10:10', 'Joshua', 10, 10, '&nbsp;مالِک خُدائ اموريان د بنى اِسرائيلو په وړاندې په وارخطايۍ آخته کړل. بنى اِسرائيلو په جبعون کښې د هغوئ قتلِ عام وکړو او د هغه سړک پورې ورپسې وُو چې بره بيت‌حورون ته تلے دے او په جنوب کښې د عزيقه او مقيده پورې يې ورباندې حملې کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5617, 'Joshua 10:11', 'Joshua', 10, 11, '&nbsp;په کوم وخت کښې چې اموريان د بنى اِسرائيلو نه لاندې درې ته تښتېدل، نو مالِک خُدائ تر عزيقه پورې په هغوئ باندې لويه ږلۍ ووروله. په ږلۍ باندې د هغې نه هم زيات مړۀ شول چې څومره بنى اِسرائيلو وژلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5618, 'Joshua 10:12', 'Joshua', 10, 12, '&nbsp;په هغه ورځ کله چې مالِک خُدائ د بنى اِسرائيلو سړو له په اموريانو باندې فتح ورکړه، يشوَع د مالِک خُدائ سره خبرې وکړې. هغۀ د بنى اِسرائيلو په مخکښې داسې وفرمائيل، ”اے نمره، د جبعون دپاسه ولاړ اوسه، اے سپوږمۍ، د ايالون په مېدان ودرېږه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5619, 'Joshua 10:13', 'Joshua', 10, 13, '&nbsp;نو نمر نېغ ودرېدو او سپوږمۍ تر هغې پورې حرکت نۀ کولو تر کومې پورې چې قوم د خپلو دشمنانو نه بدل نۀ وو اخستے. دا د ياشر په کِتاب کښې ليکلى دى. نمر د آسمان په مينځ کښې ولاړ وو او تقريباً ټوله ورځ پرې نۀ وتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5620, 'Joshua 10:14', 'Joshua', 10, 14, '&nbsp;داسې ورځ نۀ د دې نه مخکښې تېره شوې ده او نۀ د دې نه پس راغلې ده، په هغه وخت کښې مالِک خُدائ د يو سړى خبرو ته توجو وکړه، ځکه چې مالِک خُدائ د بنى اِسرائيلو دپاره جنګ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5621, 'Joshua 10:15', 'Joshua', 10, 15, '&nbsp;د دې نه پس، يشوَع او د هغۀ لښکر په جِلجال کښې کېمپ ته راواپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5622, 'Joshua 10:16', 'Joshua', 10, 16, '&nbsp;په هغه وخت هغه پينځۀ امورى بادشاهان وتښتېدل او د مقيده په غار کښې پټ شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5623, 'Joshua 10:17', 'Joshua', 10, 17, '&nbsp;يشوَع چا خبر کړو چې هغوئ په کوم ځائ کښې پټ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5624, 'Joshua 10:18', 'Joshua', 10, 18, '&nbsp;هغۀ وفرمائيل، ”د غار د خولې مخې ته يو څو غټ کاڼى راورغړوئ او څۀ څوکيداران هلته ودروئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5625, 'Joshua 10:19', 'Joshua', 10, 19, '&nbsp;خو تاسو په خپله هلته مۀ ايسارېږئ. په دشمن پسې روان اوسئ او د شا د طرف نه ورباندې حمله وکړئ، هغوئ مۀ پرېږدئ چې خپلو ښارونو ته ورسيږى. مالِک خُدائ ستاسو خُدائ پاک تاسو له په هغوئ باندې فتح درکړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5626, 'Joshua 10:20', 'Joshua', 10, 20, '&nbsp;يشوَع او د بنى اِسرائيلو سړو د اموريانو لښکر تقريباً ختم کړو، خو څۀ پاتې کسانو د ښار په دېوالونو کښې دننه د پناه ځائ پېدا کړو او ونۀ وژلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5627, 'Joshua 10:21', 'Joshua', 10, 21, '&nbsp;بيا د يشوَع ټول سړى په خېر سره د مقيده په کېمپ کښې يشوَع له واپس راغلل. د دې نه پس په هغه مُلک کښې هيچا دا جرأت نۀ شو کولے چې د بنى اِسرائيلو خِلاف څۀ ووائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5628, 'Joshua 10:22', 'Joshua', 10, 22, '&nbsp;بيا يشوَع وفرمائيل، ”د هغه غار خولۀ کولاو کړئ او هغه پينځۀ بادشاهان ما له بهر راوباسئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5629, 'Joshua 10:23', 'Joshua', 10, 23, '&nbsp;نو غار کولاو کړے شو او د يروشلم، حبرون، يرموت، لکيس او عجلون بادشاهان رابهر کړے شول', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5630, 'Joshua 10:24', 'Joshua', 10, 24, '&nbsp;او هغوئ يشوَع ته راوستلے شول. يشوَع بيا د بنى اِسرائيلو ټول سړى راوغوښتل او هغه آفسرانو له يې حُکم ورکړو چې، ”راشئ او خپلې پښې د بادشاهانو په څټُونو باندې کېږدئ.“ او هغوئ ورله په څټُونو پښې کېښودې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5631, 'Joshua 10:25', 'Joshua', 10, 25, '&nbsp;بيا يشوَع آفسرانو ته وفرمائيل، ”يرېږئ مه او نۀ چې بې‌حوصلې شئ. اراده مضبوطه کړئ او تکړه شئ ځکه چې مالِک خُدائ به ستاسو ټولو دشمنانو سره هم دغه شان کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5632, 'Joshua 10:26', 'Joshua', 10, 26, '&nbsp;بيا يشوَع بادشاهان ووژل او په پينځو ونو پورې يې راځوړند کړل او تر مازيګره پورې د هغوئ لاشونه هلته وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5633, 'Joshua 10:27', 'Joshua', 10, 27, '&nbsp;د نمرپرېواتو په وخت کښې يشوَع حُکم وکړو او د هغوئ لاشونه راکوز کړے شول او هم په هغه غار کښې وغورزولے شول چرته چې هغوئ مخکښې پټ وُو. د غار په خولۀ باندې لوئ کاڼى کېښودلے شول او هغوئ تر اوسه پورې هلته دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5634, 'Joshua 10:28', 'Joshua', 10, 28, '&nbsp;يشوَع حمله وکړه او مقيده او د هغې بادشاه يې په هغه ورځ ونيولو. هغۀ په ښار کښې ټول خلق ووژل او هيڅ څوک هم ژوندى پاتې نۀ شُو. يشوَع د مقيده بادشاه سره هم هغه شان وکړل چې څۀ يې د يريحو بادشاه سره کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5635, 'Joshua 10:29', 'Joshua', 10, 29, '&nbsp;د دې نه پس، يشوَع او د هغۀ لښکر د مقيده نه لِبناه ته لاړو او په دې يې حمله وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5636, 'Joshua 10:30', 'Joshua', 10, 30, '&nbsp;مالِک خُدائ بنى اِسرائيلو له په دې ښار او د دې په بادشاه باندې هم فتح ورکړه. يشوَع هيڅ څوک هم ژوندى پرې نۀ ښودل او هغۀ د دې بادشاه سره هم هغه شان وکړل چې څنګه يې د يريحو بادشاه سره کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5637, 'Joshua 10:31', 'Joshua', 10, 31, '&nbsp;د دې نه پس، يشوَع او د هغۀ لښکر د لِبناه نه لکيس ته لاړل، دا يې هم محاصره کړو او حمله يې پرې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5638, 'Joshua 10:32', 'Joshua', 10, 32, '&nbsp;د جنګ په دوېمه ورځ مالِک خُدائ بنى اِسرائيلو له په لکيس فتح ورکړه. څنګه چې هغوئ د لِبناه سره کړى وُو، نو هغوئ هيڅ څوک هم ژوندى پرې نۀ ښودل او په ښار کښې يې هر يو کس ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5639, 'Joshua 10:33', 'Joshua', 10, 33, '&nbsp;د جزر بادشاه هورم د لکيس د مدد دپاره راغلو، خو يشوَع هغۀ او د هغۀ لښکر له شکست ورکړو او هغۀ يو کس هم ژوندے پرې نۀ ښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5640, 'Joshua 10:34', 'Joshua', 10, 34, '&nbsp;ورپسې، يشوَع او د هغۀ لښکر د لکيس نه عجلون ته لاړل، دا يې محاصره کړو او حمله يې ورباندې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5641, 'Joshua 10:35', 'Joshua', 10, 35, '&nbsp;هغوئ هم په هغه ورځ دا قبضه کړو او هلته هر يو کس يې ووژلو، هم هغه شان چې څنګه يې د لکيس سره کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5642, 'Joshua 10:36', 'Joshua', 10, 36, '&nbsp;د دې نه پس، يشوَع او د هغۀ لښکر د عجلون نه حبرون ته وختل، حمله يې پرې وکړه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5643, 'Joshua 10:37', 'Joshua', 10, 37, '&nbsp;او قبضه يې کړو. هغوئ بادشاه، په هغه ښار او ګېرچاپېره ټولو ښارونو کښې هر يو کس ووژلو. يشوَع هغه ښار پوره تباه کړو، هم هغه شان چې څنګه هغۀ د عجلون سره کړى وُو. په دې کښې هغوئ هيڅ څوک هم ژوندے پرې نۀ ښودلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5644, 'Joshua 10:38', 'Joshua', 10, 38, '&nbsp;بيا يشوَع او د هغۀ لښکر دبير ته ورواپس شول او په دې يې حمله وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5645, 'Joshua 10:39', 'Joshua', 10, 39, '&nbsp;هغۀ دا، د دې بادشاه او ګېرچاپېره ښارونه يې قبضه کړل. هغوئ هر يو کس ووژلو. يشوَع په دبير او د دې د بادشاه سره هم هغه شان کار وکړو چې څنګه کار يې د حبرون او لِبناه او د دې د بادشاه سره کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5646, 'Joshua 10:40', 'Joshua', 10, 40, '&nbsp;يشوَع ټول مُلک قبضه کړو. هغۀ د غرونو مُلک، د نمرخاتۀ طرف ته لاندې علاقې او د نمرپرېواتۀ طرف ته د غرونو لمنې او په جنوب کښې اوچ مُلک او د دې ټولو بادشاهانو له يې شکست ورکړو. هغۀ هيڅ څوک هم ژوندے پرې نۀ ښودو، هر يو کس ووژلے شو. دا هغه څۀ وُو چې مالِک خُدائ د بنى اِسرائيلو خُدائ پاک يې حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5647, 'Joshua 10:41', 'Joshua', 10, 41, '&nbsp;يشوَع د قادِس برنيع نه واخله تر غزه پورې او د جشن ښار ګېرچاپېره علاقې نه واخله تر جبعون ښار پورې ټولو بادشاهانو له شکست ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5648, 'Joshua 10:42', 'Joshua', 10, 42, '&nbsp;يشوَع دا ټول بادشاهان او د هغوئ علاقه په يو وخت کښې فتح کړه ځکه چې مالِک خُدائ د بنى اِسرائيلو خُدائ پاک د بنى اِسرائيلو په جنګ کښې مدد کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5649, 'Joshua 10:43', 'Joshua', 10, 43, '&nbsp;د دې نه پس، يشوَع او د هغۀ لښکر په جِلجال کښې واپس کېمپ ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5650, 'Joshua 11:1', 'Joshua', 11, 1, '&nbsp;کله چې د بنى اِسرائيلو د فتحې خبر د حصور بادشاه يابين ته ورسېدو، نو هغۀ د مدون بادشاه يوباب، د سِمرون او اکشاف بادشاهانو له خبر ورولېږلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5651, 'Joshua 11:2', 'Joshua', 11, 2, '&nbsp;او په شمال کښې د غرونو مُلک ټولو بادشاهانو، د ګليل ډنډ جنوبى طرف ته د اُردن په وادۍ کښې بادشاهانو، د ګليل غرونو په لمن کښې بادشاهانو، او د دور سره نزدې د سمندر په غاړه بادشاهانو له يې هم خبر ورولېږلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5652, 'Joshua 11:3', 'Joshua', 11, 3, '&nbsp;هغۀ کنعانيانو له چې د اُردن سيند په دواړو طرفونو باندې اوسېدل، او اموريانو، حِتيانو، فرزيانو او د غرونو په مُلک کښې يبوسيانو له هم خبر ورولېږلو او داسې هغه حِويانو له يې هم خبر ورولېږلو چې هغوئ د مصفاه په مُلک کښې د حرمون غرۀ په لمن کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5653, 'Joshua 11:4', 'Joshua', 11, 4, '&nbsp;نو هغوئ د خپلو ټولو فوجيانو سره راغلل، دا دومره ډېر سړى وُو لکه چې د سمندر په غاړه شګې وى. د هغوئ سره ډېر آسونه او جنګى ګاډۍ هم وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5654, 'Joshua 11:5', 'Joshua', 11, 5, '&nbsp;دې ټولو بادشاهانو په خپلو کښې اِتحاد وکړو او په يو ځائ راغلل او د بنى اِسرائيلو خِلاف جنګ کولو دپاره يې د ميروم خوَړ سره خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5655, 'Joshua 11:6', 'Joshua', 11, 6, '&nbsp;مالِک خُدائ يشوَع ته وفرمائيل، ”د هغوئ نه مۀ يرېږه. سبا تر دې وخته پورې به ما هغوئ ټول د بنى اِسرائيلو دپاره وژلى وى. بيا تۀ به ضرور د هغوئ آسونه ګوډ کړې او د هغوئ جنګى ګاډۍ به وسوزوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5656, 'Joshua 11:7', 'Joshua', 11, 7, '&nbsp;نو يشوَع او د هغۀ ټولو سړو د ميروم د خوَړ سره په هغوئ باندې اچانک حمله وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5657, 'Joshua 11:8', 'Joshua', 11, 8, '&nbsp;مالِک خُدائ بنى اِسرائيلو له په هغوئ باندې فتح ورکړه، اِسرائيليان ورپسې وُو او په شمال کښې تر مسرفات مائم او صيدا او نمرخاتۀ طرف تر مصفاه وادۍ پورې ورپسې وُو. جنګ تر هغې پورې جارى وو چې د دشمن يو کس هم ژوندے پاتې نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5658, 'Joshua 11:9', 'Joshua', 11, 9, '&nbsp;يشوَع د هغوئ سره هم هغه شان وکړل چې څنګه مالِک خُدائ حُکم کړے وو يعنې هغۀ د هغوئ آسونه شل ګوډ کړل او جنګى ګاډۍ يې ورله وسوزولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5659, 'Joshua 11:10', 'Joshua', 11, 10, '&nbsp;بيا يشوَع راواپس شو، حصور يې ونيولو او د دې بادشاه يې ووژلو. په هغه وخت کښې حصور د ټولو بادشاهتونو مرکزى ښار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5660, 'Joshua 11:11', 'Joshua', 11, 11, '&nbsp;هغوئ هلته هر يو کس ووژلو، هيڅ څوک هم ژوندے پاتې نۀ شو او ښار وسوزولے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5661, 'Joshua 11:12', 'Joshua', 11, 12, '&nbsp;يشوَع هغه ټول ښارونه او د دې بادشاهان ونيول، هر يو کس يې ووژلو، هم هغه شان چې څنګه د مالِک خُدائ خِدمت کوونکى موسىٰ حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5662, 'Joshua 11:13', 'Joshua', 11, 13, '&nbsp;خو بنى اِسرائيلو هغه يو ښار هم ونۀ سوزولو کوم چې په غونډو باندې جوړ شوے وو خو يشوَع صِرف حصور سوزولے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5663, 'Joshua 11:14', 'Joshua', 11, 14, '&nbsp;بنى اِسرائيلو د دې ښارونو نه ټول مالِ غنيمت او څاروى بوتلل او د خپلو ځانونو دپاره يې وساتل. خو هغوئ ټول کسان ووژل، هيڅ څوک هم ژوندى پاتې نۀ شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5664, 'Joshua 11:15', 'Joshua', 11, 15, '&nbsp;مالِک خُدائ خپل خِدمت کوونکى موسىٰ له حُکم ورکړے وو، موسىٰ دا حُکم يشوَع له ورکړو او يشوَع ورباندې عمل وکړو. هغۀ هغه هر څۀ وکړل چې مالِک خُدائ موسىٰ ته د هغې حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5665, 'Joshua 11:16', 'Joshua', 11, 16, '&nbsp;يشوَع هغه ټول مُلک قبضه کړو د غرونو مُلک، د غرونو لمنې، چې په شمال او جنوب دواړو طرفونو باندې وُو، د جشن ټوله علاقه او د دې جنوبى طرف ته خُشک مُلک او هم دې سره د اُردن د وادۍ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5666, 'Joshua 11:19', 'Joshua', 11, 19, '&nbsp;جبعون هغه يواځينے ښار وو چې د بنى اِسرائيلو سره يې صُلح وکړه، هلته څۀ حِويان اوسېدل. باقى نور ټول په جنګ کښې فتح شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5667, 'Joshua 11:20', 'Joshua', 11, 20, '&nbsp;مالِک خُدائ هغوئ په خپله تکړه کړى وُو چې د بنى اِسرائيلو سره جنګ وکړى، نو داسې هغوئ بېخى تباه کړے شول او ټول په بې‌رحمۍ سره ووژلے شول. دا هغه څۀ وُو چې مالِک خُدائ د دې حُکم موسىٰ له ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5668, 'Joshua 11:21', 'Joshua', 11, 21, '&nbsp;په هغه وخت کښې يشوَع لاړو او د دېوانو نسل عناقيان يې تباه کړل چې د غرونو په مُلک کښې، حبرون، دبير، عناب او د يهوداه او بنى اِسرائيل د غرونو په ټول مُلک کښې اوسېدل. يشوَع هغوئ او د هغوئ ښارونه پوره تباه کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5669, 'Joshua 11:22', 'Joshua', 11, 22, '&nbsp;د بنى اِسرائيلو په مُلک کښې يو عناقے هم پاتې نۀ شو، اګر چې څۀ عناقيان په غزه، جات او اشدود کښې پاتې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5670, 'Joshua 11:23', 'Joshua', 11, 23, '&nbsp;يشوَع هغه ټول مُلک قبضه کړو، هم هغه شان چې څنګه مالِک خُدائ موسىٰ ته حُکم کړے وو. يشوَع دا بنى اِسرائيلو له ورکړو چې خپل ميراث يې شى او په هره قبيله باندې يې په حِصو کښې تقسيم کړو. نو بيا په هغه مُلک کښې جنګونه ختم شول او امن و امان شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5671, 'Joshua 12:1', 'Joshua', 12, 1, '&nbsp;بنى اِسرائيلو دوو بادشاهانو له شکست ورکړو، نو د اُردن نمرخاتۀ طرف ته، د ارنون وادۍ نه واخله د اُردن تر وادۍ پورې او هم داسې په شمال کښې د حرمون غر پورې ټول مُلک يې فتح کړے وو او قبضه يې پرې کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5672, 'Joshua 12:2', 'Joshua', 12, 2, '&nbsp;يو امورى بادشاه سيحون وو چې هغۀ به په حسبون باندې بادشاهى کوله. د هغۀ په بادشاهۍ کښې نيم جِلعاد شامل وو، د عروعير نه واخله چې د ارنون وادۍ په غاړه وو او د هغه وادۍ په مينځ کښې ښار او هم داسې د يبوق سيند پورې چې دا د عمون سرحد وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5673, 'Joshua 12:3', 'Joshua', 12, 3, '&nbsp;په دې کښې د اُردن وادى يعنې په جنوب کښې د ګليل درياب نه واخله د مړ درياب نمرخاتۀ طرف تر بيت‌يسيموت پورې او د پِسګه غر د لمنو پورې علاقې شاملې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5674, 'Joshua 12:4', 'Joshua', 12, 4, '&nbsp;هغوئ د بسن بادشاه عوج له هم شکست ورکړو، څوک چې د رفائيم آخرى پاتې شوے وو، هغۀ په عستارات او ادرعى باندې بادشاهى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5675, 'Joshua 12:5', 'Joshua', 12, 5, '&nbsp;د هغۀ په بادشاهۍ کښې د حرمون غر، سلکه او د جسور سرحدونو پورې ټول بسن او معکه او نيم جِلعاد او هم داسې د حسبون بادشاه سيحون د علاقې پورې مُلک په کښې شامل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5676, 'Joshua 12:6', 'Joshua', 12, 6, '&nbsp;موسىٰ او بنى اِسرائيلو دې دوو بادشاهانو له شکست ورکړے وو. د مالِک خُدائ خِدمت کوونکى موسىٰ د هغوئ مُلک د روبين، جاد او د منسى نيمې قبيلې له د دې دپاره ورکړے وو چې د هغوئ خپل ميراث شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5677, 'Joshua 12:7', 'Joshua', 12, 7, '&nbsp;نو يشوَع او بنى اِسرائيلو د اُردن نمرپرېواتۀ طرف ته دې ټولو بادشاهانو له شکست ورکړو چې په دې کښې د لبنان وادۍ بعل‌جاد نه واخله په جنوب کښې د ادوم سره نزدې د خلق غر پورې علاقې شاملې وې. يشوَع دا مُلک په قبيلو باندې تقسيم کړو او دا يې ورکړو چې پوخ ميراث يې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5678, 'Joshua 12:8', 'Joshua', 12, 8, '&nbsp;په دې حِصه کښې د غرونو مُلک، نمرپرېواتۀ طرف ته د غرونو لمنې، د اُردن وادى او د دې لمنې، نمرخاتۀ طرف ته کوزه علاقه او په جنوب کښې خُشکه علاقه شامله وه. په دې علاقه کښې حِتيان، اموريان، کنعانيان، فرزيان، حِويان او يبوسيان اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5679, 'Joshua 12:9', 'Joshua', 12, 9, '&nbsp;بنى اِسرائيلو چې کومو بادشاهانو له شکست ورکړو هغه دا دى، يريحو، عى چې بيت‌ايل ته نزدې وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5680, 'Joshua 12:10', 'Joshua', 12, 10, '&nbsp;يروشلم، حبرون،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5681, 'Joshua 12:11', 'Joshua', 12, 11, '&nbsp;يرموت، لکيس،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5682, 'Joshua 12:12', 'Joshua', 12, 12, '&nbsp;عجلون، جزر،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
