(5695, 'Joshua 13:1', 'Joshua', 13, 1, '&nbsp;اوس يشوَع ډېر بوډا شوے وو. مالِک خُدائ هغۀ ته وفرمائيل، ”تۀ ډېر بوډا شوے يې خو تر اوسه پورې په ډېره علاقه باندې قبضه کول پاتې دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
